add_filter( 'woocommerce_add_to_cart_validation', 'perfectpixel_only_one_product_in_cart', 9999, 2 );

function perfectpixel_only_one_product_in_cart( $passed, $product_id ) {
	if ( ! $passed || ! WC()->cart || WC()->cart->is_empty() ) {
		return $passed;
	}
	// Adding the same product again: let WooCommerce handle the quantity.
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( (int) $item['product_id'] === (int) $product_id && 1 === count( WC()->cart->get_cart() ) ) {
			return $passed;
		}
	}
	WC()->cart->empty_cart();
	$notice = '{{one_product_notice}}';
	if ( '' !== trim( $notice ) ) {
		wc_add_notice( $notice, 'notice' );
	}
	return $passed;
}
